// 原claim与三源真实写者的NPC门；会话由夹具创建，非自然World或人物接续行为证明。
#include "visit_appointment_test_fixture.hpp"
#include "resident/domains/interaction/visit_appointments/visit_appointment_authored.hpp"
#include "resident/domains/interaction/visit_appointments/visit_appointment_control.hpp"
#include "resident/domains/family/family_model.hpp"
namespace {
struct NpcInvitationFixture:InvitationFixture {
 VisitReceptionCatalog reception;VisitReceptionState claims;VisitAppointmentIntentCatalog intents;FamilyState family;
 NpcInvitationFixture(){family.founder_actor_id="sender";auto& d=dialogues.dialogues.front();d.entry="receive";for(auto& n:d.nodes)if(n.id=="receive")n.next="offer_invitation";reception.intents.push_back({"reception","recipient","visiting","receive",4,{}});intents.intents.push_back({"offer","reception","invitation",{{"receive",{}}}});}
 VisitAppointmentAuthorshipRead authored(){return {intents,reception,claims,interactions};}
 bool source_valid(){auto a=authored();VisitAppointmentHistoricalSources h;h.authored=&a;h.player_before_fact=[this](Integer tick,const StableId& fact){return read_visit_appointment_player_before_fact(common,family,nullptr,tick,fact);};return validate_visit_appointments(common,*definitions,messages,catalog,appointments,prior,dialogues,catalog2,state,h).ok&&validate_visit_appointment_cached_results(common,&state).ok;}
 StableId control(){auto id=common.next_id("family");need(id.ok,"fixture original control instance allocated");FamilyChoice choice;choice.kind="family_succession";choice.guardian_actor_id="sender";choice.heir_actor_id="recipient";choice.tick=common.tick();family.facts.insert(id.value,choice);family.successions.push_back(id.value);need(common.append_fact({id.value,"family_succession","family"}).ok,"fixture original typed control source appended");common.state().metadata.player_actor_id="recipient";return id.value;}
 AuthoredVisitAppointment ready(){auto m=apply("sender",LeaveVisitMessage{"visiting"});need(m.ok,"real original note posted");meet("recipient","receive");common.state().metadata.player_actor_id="sender";need(record_visit_reception_claim_in_candidate(common,claims,reception,catalog,dialogues,interactions,"recipient","reception").ok,"real claim binds allocated current NPC session");const auto claim=claims.claims.order().back();auto received=apply("recipient",ReceiveVisitMessage{m.value});need(received.ok,"real NPC receipt precedes invitation");interactions.interactions.front().node_id="offer_invitation";return {"offer",m.value,received.value,claim};}
 Outcome<AuthoredVisitAppointmentQuote> prepare_npc(const AuthoredVisitAppointment& command){auto a=authored();return preview_authored_visit_appointment(common,messages,catalog,appointments,prior,dialogues,access,catalog2,state,a,"recipient",command);}
 Outcome<StableId> write_npc(const AuthoredVisitAppointment& command){auto q=prepare_npc(command);if(!q.ok)return {false,{},q.error};auto a=authored();return apply_authored_visit_appointment_in_candidate(common,messages,catalog,appointments,prior,dialogues,access,catalog2,state,a,"recipient",command,q.value);}
};
}
int main(){try{
 NpcInvitationFixture f;need(validate_visit_appointment_intents(f.intents,f.catalog2,f.reception,f.catalog,f.appointments,f.dialogues).ok,"explicit new dated invitation route validated");auto command=f.ready();const auto before=f.state;auto offer=f.write_npc(command);need(offer.ok&&f.source_valid(),"real NPC source writes an invitation without pretending a player result");const auto* source=f.state.offered.find(offer.value);need(source&&source->authored_origin&&!source->player_receipt,"exact real intent and claim retained");ReceiptDetails advance;advance.data=AdvanceDetails{};auto diff=visit_appointment_new_player_source(&before,&f.state,"sender","advance",advance,f.common.tick());need(diff.ok&&diff.value.empty(),"Advance never binds NPC promise as player choice");need(!visit_appointment_new_player_source(&before,&f.state,"sender","wait",advance,f.common.tick()).ok,"unrelated zero time request cannot create NPC promise");
 VisitAppointmentAccess access(f.common,f.state);auto unknown=access.known_visit_appointment("sender",offer.value);need(unknown.ok&&!unknown.value,"NPC promise does not remotely inform original sender");auto commitments=access.own_commitments("recipient",0,8);need(commitments.ok&&commitments.value.size()==1,"NPC own promise exists without reading invitee acceptance");
 auto saved=f.state;f.state.offered.find(offer.value)->authored_origin.reset();need(!f.source_valid(),"removing origin cannot become an unbound player source");f.state=saved;f.state.offered.find(offer.value)->authored_origin->reception_claim_fact_id=command.received_fact_id;need(!f.source_valid(),"received message is not a session claim");f.state=saved;const auto succession=f.control();need(f.source_valid(),"later control change preserves earlier genuine NPC promise");auto rows=f.common.state().facts.rows();const auto head=*f.common.state().facts.find(succession);f.common.state().facts=OrderedTable<FactRecord>{};for(const auto& row:rows){if(row.first==offer.value)f.common.state().facts.insert(succession,head);if(row.first!=succession)f.common.state().facts.insert(row.first,row.second);}need(!f.source_valid(),"same tick control cannot cross invitation numeric/Common boundary");
 NpcInvitationFixture changed;auto next=changed.ready();changed.control();need(!changed.prepare_npc(next).ok,"new player cannot reuse old NPC claim through authored writer");auto actual=changed.commit("recipient",OfferVisitAppointment{"invitation",next.message_fact_id});need(actual.ok&&changed.source_valid(),"same person instead makes real bound player offer");changed.common.state().results=OrderedTable<std::shared_ptr<const CommitResult>>{};changed.common.state().history.clear();auto* forged=changed.state.offered.find(actual.value);forged->player_receipt.reset();forged->authored_origin=VisitAppointmentAuthoredOrigin{"offer",next.claim_fact_id};need(!changed.source_valid(),"evicted player binding cannot be replaced by older NPC claim");
 auto malformed=f.intents;malformed.intents.front().route.front().node_id="deposit";need(!validate_visit_appointment_intents(malformed,f.catalog2,f.reception,f.catalog,f.appointments,f.dialogues).ok,"new intent route starts from real original receipt declaration");auto json=encode_visit_appointment_intents(f.intents);need(decode_visit_appointment_intents(json,f.catalog2,f.reception,f.catalog,f.appointments,f.dialogues).ok,"intent strict JSON retains source policy and finite route");std::cout<<checks<<" authored invitation source checks; natural Talk/Director/World deferred\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
